// Recibe batch de items con binary.data y json.name
// Procesa todos los items del batch
const items = $input.all();
return items.map(item => {
  if (item.binary?.data) {
    item.binary.data.fileName = item.json.name;
    item.binary.data.metadata = item.binary.data.metadata || {};
    item.binary.data.metadata.fileId = item.json.id;
  }
  return item;
});
